-- Упражнения книги 19, глава 17 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-raid-capacity', 0, 'func', 'Ёмкость и отказоустойчивость массива', 'Напишите функцию raid_summary(level, sizes, spares). level — одна из строк raid0, raid1, raid5, raid6, raid10; sizes — размеры рабочих дисков в гигабайтах, spares — размеры запасных. Правила задачи: массив использует размер самого маленького рабочего диска для каждого участника; минимальное число рабочих дисков: raid0 — 2, raid1 — 2, raid5 — 3, raid6 — 4, raid10 — 2 (raid10 здесь — md raid10 с двумя копиями, он работает и с нечётным числом дисков). Полезная ёмкость: raid0 — n×m, raid1 — m, raid5 — (n−1)×m, raid6 — (n−2)×m, raid10 — n×m//2 (целочисленное деление), где n — число рабочих дисков, m — самый маленький из них. Гарантированно переживаемые отказы: raid0 — 0, raid1 — n−1, raid5 — 1, raid6 — 2, raid10 — 1; в лучшем случае (когда отказавшие диски удачно распределены): raid0 — 0, raid1 — n−1, raid5 — 1, raid6 — 2, raid10 — n//2. Запасной диск годится, только если его размер не меньше m. Верните кортеж (ёмкость, гарантированно, в лучшем случае, число пригодных запасных). Для неизвестного уровня или слишком малого числа дисков верните None.', 'def raid_summary(level, sizes, spares):
    pass
', 'Сначала проверьте минимум дисков, потом m = min(sizes) и ветка по уровню; запасные считайте генератором по условию s >= m.', '{"func": "raid_summary", "tests": [{"args": ["raid5", [4000, 4000, 4000, 4000], []], "expected": {"__tuple__": [12000, 1, 1, 0]}}, {"args": ["raid5", [4000, 4000, 2000], [2000, 4000]], "expected": {"__tuple__": [4000, 1, 1, 2]}}, {"args": ["raid6", [8000, 8000, 8000, 8000, 8000, 8000], [8000]], "expected": {"__tuple__": [32000, 2, 2, 1]}}, {"args": ["raid6", [1000, 1000, 1000], []], "expected": null}, {"args": ["raid1", [500, 1000], [400]], "expected": {"__tuple__": [500, 1, 1, 0]}}, {"args": ["raid1", [1000, 1000, 1000], [1000, 999, 1001]], "expected": {"__tuple__": [1000, 2, 2, 2]}}, {"args": ["raid0", [300, 300, 600], []], "expected": {"__tuple__": [900, 0, 0, 0]}}, {"args": ["raid10", [1000, 1000, 1000, 1000], []], "expected": {"__tuple__": [2000, 1, 2, 0]}}, {"args": ["raid10", [1000, 1000, 1000, 1000, 1000], [1000]], "expected": {"__tuple__": [2500, 1, 2, 1]}}, {"args": ["raid10", [1001, 1001, 1001], []], "expected": {"__tuple__": [1501, 1, 1, 0]}}, {"args": ["raid10", [1000], []], "expected": null}, {"args": ["raid50", [1, 2, 3, 4], []], "expected": null}, {"args": ["raid5", [2000, 2000], []], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-mdstat-degraded', 1, 'func', 'Деградировавшие массивы в /proc/mdstat', 'Напишите функцию degraded_arrays(text): text — содержимое /proc/mdstat. Блок массива начинается со строки «имя : состояние уровень участники…» с первого символа, за ней идут строки с отступом; строки Personalities и unused devices блоками не являются. Участник записан как sdb1[0], а пометка (F) в скобках (она может стоять вместе с другими буквами, например (SF)) означает отказавший диск. Массив считается проблемным, если у него есть пара [n/m] и m < n (на строке состояния, например [4/3] [UUU_]), либо он inactive; у raid0 пары [n/m] нет, и такой массив пропускается (если он не inactive). Для каждого проблемного массива верните кортеж (имя, сколько дисков не хватает n−m или None для inactive, отсортированный список имён отказавших дисков без номеров роли, действие, процент, оценка завершения в минутах). Действие — одно из слов resync, recovery, reshape, check, repair, когда в блоке есть фрагмент вида «recovery = 12.6%» (пробелы вокруг = могут быть любыми, процент — число с точкой, его верните как float); если такого фрагмента нет (например, resync=PENDING), действие, процент и оценка равны None. Оценка — число из finish=127.5min как float, если такого фрагмента нет, то None. Результат отсортируйте по имени массива как по строкам.', 'def degraded_arrays(text):
    pass
', 'Режьте текст на блоки по строкам, начинающимся с «имя : »; внутри блока ищите регулярками [n/m], (F) у участников и «(resync|recovery|…) = N%».', '{"func": "degraded_arrays", "tests": [{"args": ["Personalities : [raid1] [raid6] [raid5] [raid4]\nmd0 : active raid1 sdb1[0] sdc1[1]\n      10475520 blocks super 1.2 [2/2] [UU]\n      bitmap: 0/1 pages [0KB], 65536KB chunk\n\nmd1 : active raid5 sdh1[6] sdg1[4] sdf1[3] sde1[2](F) sdd1[1] sdc1[0]\n      1464725760 blocks super 1.2 level 5, 64k chunk, algorithm 2 [6/5] [UU_UUU]\n      [==>..................]  recovery = 12.6% (37043392/292945152) finish=127.5min speed=33440K/sec\n      bitmap: 3/3 pages [12KB], 65536KB chunk\n\nmd2 : active raid0 sdi1[0] sdj1[1]\n      2096128 blocks super 1.2 512k chunks\n\nunused devices: <none>\n"], "expected": [{"__tuple__": ["md1", 1, ["sde1"], "recovery", 12.6, 127.5]}]}, {"args": ["Personalities : [raid1] [raid6] [raid5] [raid4] [raid10]\nmd127 : inactive sdb[1](S) sdc[0](S)\n      5860271104 blocks super 1.2\n\nmd3 : active raid6 sdf1[3] sde1[2] sdd1[1] sdc1[0]\n      2095104 blocks super 1.2 level 6, 512k chunk, algorithm 2 [4/4] [UUUU]\n      [=====>...............]  check = 27.3% (286720/1047552) finish=2.1min speed=6012K/sec\n\nunused devices: <none>\n"], "expected": [{"__tuple__": ["md127", null, [], null, null, null]}]}, {"args": ["Personalities :\nunused devices: <none>\n"], "expected": []}, {"args": ["Personalities : [raid1] [raid6] [raid5] [raid4]\nmd10 : active (auto-read-only) raid1 sdb2[0]\n      4189184 blocks super 1.2 [2/1] [U_]\n      resync=PENDING\n\nmd2 : active raid1 sdd1[2] sdb1[0] sdc1[1](F)\n      10475520 blocks super 1.2 [2/1] [U_]\n      [=>...................]  recovery =  8.4% (878016/10475520) finish=5.2min speed=30521K/sec\n      bitmap: 1/1 pages [4KB], 65536KB chunk\n\nmd5 : active raid6 sdk1[5] sdj1[4](F) sdi1[3] sdh1[2](F) sdg1[1] sdf1[0] sdl1[6](S)\n      4190208 blocks super 1.2 level 6, 512k chunk, algorithm 2 [6/4] [UU_U_U]\n      [>....................]  reshape =  1.0% (10240/1047552) finish=14.5min speed=1191K/sec\n\nunused devices: <none>\n"], "expected": [{"__tuple__": ["md10", 1, [], null, null, null]}, {"__tuple__": ["md2", 1, ["sdc1"], "recovery", 8.4, 5.2]}, {"__tuple__": ["md5", 2, ["sdh1", "sdj1"], "reshape", 1.0, 14.5]}]}, {"args": ["Personalities : [raid1]\nmd0 : active raid1 nvme0n1p2[1] nvme1n1p2[0]\n      498368 blocks super 1.2 [2/2] [UU]\n\nmd1 : active raid1 nvme1n1p3[2] nvme0n1p3[1]\n      975101952 blocks super 1.2 [2/1] [_U]\n      [===========>.........]  recovery = 56.2% (548012032/975101952) finish=45.3min speed=157044K/sec\n      bitmap: 8/8 pages [32KB], 65536KB chunk\n\nunused devices: <none>\n"], "expected": [{"__tuple__": ["md1", 1, [], "recovery", 56.2, 45.3]}]}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-replace-sequence', 2, 'func', 'Замена отказавшего диска по шагам', 'Смоделируйте упрощённый md-массив. Функция replace_sequence(level, n, devices, spares, commands): level — raid1, raid5 или raid6, n — число слотов массива, devices — имена рабочих дисков, spares — имена запасных, commands — список строк-команд. Нужное число рабочих дисков, чтобы данные были целы: raid1 — 1, raid5 — n−1, raid6 — n−2. Диск может быть в одном из пяти списков: active (синхронизирован), rebuilding (собирается), spare, failed (помечен отказавшим, но ещё числится в массиве). Команды: «fail X» — диск из active, rebuilding или spare переходит в failed; если это был active или rebuilding и есть запасные, а в active осталось не меньше нужного числа дисков, то первый запасной (по порядку) сразу переходит в rebuilding; неизвестный диск отвергается. «remove X» — убирает диск, который сейчас в failed или spare; иначе (active, rebuilding или неизвестный) команда отвергается. «add X» — если имя уже есть в любом из списков (в том числе в failed), команда отвергается; иначе, если слот свободен (active + rebuilding < n) и в active не меньше нужного числа дисков, диск становится rebuilding, а если нет — spare. «done» (без аргумента) — если в active не меньше нужного числа дисков, все rebuilding становятся active; в остальных случаях (в том числе когда ничего не собирается) она ничего не делает и не отвергается. Любая другая команда отвергается. После всех команд верните кортеж (состояние, число active, число spare, число failed, число отвергнутых команд). Состояние: «FAILED», если active меньше нужного числа; иначе «clean», к которому добавляется «, degraded» при active < n и затем «, recovering», если есть rebuilding.', 'def replace_sequence(level, n, devices, spares, commands):
    pass
', 'Заведите четыре списка и счётчик отвергнутых; каждую команду разберите через split(), после fail запускайте запасной только если active >= нужного.', '{"func": "replace_sequence", "tests": [{"args": ["raid1", 2, ["sdb1", "sdc1"], [], ["fail sdc1", "remove sdc1", "add sdd1", "done"]], "expected": {"__tuple__": ["clean", 2, 0, 0, 0]}}, {"args": ["raid1", 2, ["sdb1", "sdc1"], [], ["fail sdc1", "remove sdc1", "add sdd1"]], "expected": {"__tuple__": ["clean, degraded, recovering", 1, 0, 0, 0]}}, {"args": ["raid5", 4, ["sdb1", "sdc1", "sdd1", "sde1"], ["sdf1"], ["fail sdc1"]], "expected": {"__tuple__": ["clean, degraded, recovering", 3, 0, 1, 0]}}, {"args": ["raid5", 4, ["sdb1", "sdc1", "sdd1", "sde1"], ["sdf1"], ["fail sdc1", "done", "remove sdc1", "add sdc2"]], "expected": {"__tuple__": ["clean", 4, 1, 0, 0]}}, {"args": ["raid5", 3, ["sdb1", "sdc1", "sdd1"], [], ["fail sdb1", "fail sdc1"]], "expected": {"__tuple__": ["FAILED", 1, 0, 2, 0]}}, {"args": ["raid5", 3, ["sdb1", "sdc1", "sdd1"], [], ["remove sdb1", "add sdc1", "fail sdz1", "reboot", "done"]], "expected": {"__tuple__": ["clean", 3, 0, 0, 4]}}, {"args": ["raid6", 4, ["a", "b", "c", "d"], [], ["fail a", "fail b", "add e", "add f", "done"]], "expected": {"__tuple__": ["clean", 4, 0, 2, 0]}}, {"args": ["raid6", 4, ["a", "b", "c", "d"], [], ["fail a", "fail b", "fail c"]], "expected": {"__tuple__": ["FAILED", 1, 0, 3, 0]}}, {"args": ["raid5", 3, ["sdb1", "sdc1", "sdd1"], ["sde1"], ["fail sdb1", "fail sde1", "remove sde1", "remove sdb1"]], "expected": {"__tuple__": ["clean, degraded", 2, 0, 0, 0]}}, {"args": ["raid5", 3, ["sdb1", "sdc1", "sdd1"], ["sde1", "sdf1"], ["fail sdb1", "fail sdc1", "add sdg1", "done"]], "expected": {"__tuple__": ["FAILED", 1, 2, 2, 0]}}, {"args": ["raid1", 2, ["x", "y"], ["z"], []], "expected": {"__tuple__": ["clean", 2, 1, 0, 0]}}, {"args": ["raid1", 2, ["x", "y"], [], ["add z", "remove z", "add z"]], "expected": {"__tuple__": ["clean", 2, 1, 0, 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-detail-report', 3, 'func', 'Разбор mdadm --detail', 'Напишите функцию detail_report(text): text — вывод mdadm --detail. Верните словарь с ключами level (значение поля Raid Level, например raid5), state (значение поля State без пробелов по краям), active, missing, faulty, rebuilding, spares (отсортированные списки) и progress. Строки до таблицы имеют вид «Поле : значение» с пробелами по краям. Таблица начинается строкой с заголовками Number Major Minor RaidDevice State; в каждой строке таблицы поля разделены пробелами: номер, major, minor, номер слота RaidDevice (или «-»), затем слова состояния и в конце путь устройства (может отсутствовать). По словам состояния (проверяйте в таком порядке) определяется категория: removed — слот пуст (в missing попадает номер слота как int), faulty — путь в faulty, rebuilding — путь в rebuilding, spare — путь в spares, active — путь в active. Остальные слова (sync, writemostly, set-A и т. п.) игнорируйте; строки таблицы короче пяти полей и пустые пропускайте. progress — целое число процентов из строки вида «Rebuild Status : 42% complete» (то же для Resync, Reshape и Check), или None, если такой строки нет.', 'def detail_report(text):
    pass
', 'Поле до таблицы ловится регуляркой «^(Raid Level|State)\s*:\s*(.*)$»; после строки Number … RaidDevice переключитесь в режим таблицы и разбирайте строки через split().', '{"func": "detail_report", "tests": [{"args": ["/dev/md0:\n           Version : 1.2\n     Creation Time : Mon Nov  2 10:15:41 2026\n        Raid Level : raid5\n        Array Size : 20954112 (19.98 GiB 21.46 GB)\n     Used Dev Size : 10477056 (9.99 GiB 10.73 GB)\n      Raid Devices : 3\n     Total Devices : 3\n       Persistence : Superblock is persistent\n\n       Update Time : Tue Nov  3 08:02:17 2026\n             State : clean, degraded, recovering\n    Active Devices : 2\n   Working Devices : 3\n    Failed Devices : 1\n     Spare Devices : 1\n\n            Layout : left-symmetric\n        Chunk Size : 512K\n\nConsistency Policy : resync\n\n    Rebuild Status : 42% complete\n\n              Name : srv1:0  (local to host srv1)\n              UUID : 5b2f1c0e:7d9a4e11:b0c8a3d2:19e4f6a7\n            Events : 211\n\n    Number   Major   Minor   RaidDevice State\n       0       8       17        0      active sync   /dev/sdb1\n       1       8       33        1      active sync   /dev/sdc1\n       4       8       65        2      spare rebuilding   /dev/sde1\n\n       3       8       49        -      faulty   /dev/sdd1\n"], "expected": {"level": "raid5", "state": "clean, degraded, recovering", "active": ["/dev/sdb1", "/dev/sdc1"], "missing": [], "faulty": ["/dev/sdd1"], "rebuilding": ["/dev/sde1"], "spares": [], "progress": 42}}, {"args": ["/dev/md1:\n           Version : 1.2\n        Raid Level : raid1\n        Array Size : 10475520 (9.99 GiB 10.73 GB)\n      Raid Devices : 2\n     Total Devices : 1\n       Persistence : Superblock is persistent\n\n       Update Time : Thu Oct  3 09:09:36 2013\n             State : clean, degraded\n    Active Devices : 1\n   Working Devices : 1\n    Failed Devices : 0\n     Spare Devices : 0\n\n              Name : ubuntu:1  (local to host ubuntu)\n              UUID : ebe7bfba:a20bf402:f7954545:d920460f\n            Events : 160\n\n    Number   Major   Minor   RaidDevice State\n       0       8       17        0      active sync   /dev/sdb1\n       -       0        0        1      removed\n"], "expected": {"level": "raid1", "state": "clean, degraded", "active": ["/dev/sdb1"], "missing": [1], "faulty": [], "rebuilding": [], "spares": [], "progress": null}}, {"args": ["/dev/md4:\n           Version : 1.2\n        Raid Level : raid10\n        Array Size : 41908224 (39.97 GiB 42.91 GB)\n      Raid Devices : 4\n     Total Devices : 5\n             State : active, checking\n    Active Devices : 4\n   Working Devices : 5\n    Failed Devices : 0\n     Spare Devices : 1\n\n            Layout : near=2\n        Chunk Size : 512K\n\n      Check Status : 17% complete\n\n    Number   Major   Minor   RaidDevice State\n       0       8       16        0      active sync set-A   /dev/sdb\n       1       8       32        1      active sync set-B   /dev/sdc\n       2       8       48        2      active sync set-A   /dev/sdd\n       3       8       64        3      active sync set-B   /dev/sde\n\n       4       8       80        -      spare   /dev/sdf\n"], "expected": {"level": "raid10", "state": "active, checking", "active": ["/dev/sdb", "/dev/sdc", "/dev/sdd", "/dev/sde"], "missing": [], "faulty": [], "rebuilding": [], "spares": ["/dev/sdf"], "progress": 17}}, {"args": ["/dev/md2:\n        Raid Level : raid6\n      Raid Devices : 6\n             State : active, FAILED\n    Active Devices : 3\n\n    Number   Major   Minor   RaidDevice State\n       0       8       17        0      active sync   /dev/sdb1\n       -       0        0        1      removed\n       2       8       49        2      active sync   /dev/sdd1\n       -       0        0        3      removed\n       4       8       81        4      active sync   /dev/sdf1\n       -       0        0        5      removed\n       6       8       97        -      faulty   /dev/sdg1\n       7       8      113        -      faulty   /dev/sdh1\n"], "expected": {"level": "raid6", "state": "active, FAILED", "active": ["/dev/sdb1", "/dev/sdd1", "/dev/sdf1"], "missing": [1, 3, 5], "faulty": ["/dev/sdg1", "/dev/sdh1"], "rebuilding": [], "spares": [], "progress": null}}, {"args": ["/dev/md0:\n        Raid Level : raid1\n      Raid Devices : 2\n             State : clean\n    Active Devices : 2\n\n    Number   Major   Minor   RaidDevice State\n       0     259        2        0      active sync   /dev/nvme0n1p2\n       1     259        6        1      active sync writemostly   /dev/nvme1n1p2\n"], "expected": {"level": "raid1", "state": "clean", "active": ["/dev/nvme0n1p2", "/dev/nvme1n1p2"], "missing": [], "faulty": [], "rebuilding": [], "spares": [], "progress": null}}, {"args": [""], "expected": {"level": "", "state": "", "active": [], "missing": [], "faulty": [], "rebuilding": [], "spares": [], "progress": null}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-smart-triage', 4, 'func', 'Оценка таблицы SMART-атрибутов', 'Напишите функцию smart_triage(text): text — вывод smartctl -A. Строка атрибута — это строка, в которой не меньше десяти слов, а первое слово состоит из цифр; остальные строки (заголовки, пустые) игнорируйте. Поля по порядку: ID#, ATTRIBUTE_NAME, FLAG, VALUE, WORST, THRESH, TYPE, UPDATED, WHEN_FAILED, а остальное — RAW_VALUE; нужен только ID, WHEN_FAILED и первое целое число в RAW_VALUE (например, 31 в «31 (Min/Max 22/46)»). Правила. Атрибут «падает сейчас», если WHEN_FAILED равен FAILING_NOW. Атрибут «настораживает» в одном из случаев: WHEN_FAILED равен In_the_past; ID один из 5, 197, 198 и сырое значение больше нуля; ID один из 190, 194 и сырое значение не меньше 55. Верните кортеж (вердикт, список ID). Вердикт FAIL, если есть хотя бы один падающий сейчас атрибут; тогда в списке отсортированные ID падающих сейчас. Иначе WARN, если есть настораживающие; тогда в списке их отсортированные ID без повторов. Иначе кортеж (''OK'', []).', 'def smart_triage(text):
    pass
', 'Строку атрибута проверяйте условием len(t) >= 10 and t[0].isdigit(); сырое значение — re.match(r''\d+'', t[9]).', '{"func": "smart_triage", "tests": [{"args": ["smartctl 7.4 2023-08-01 r5530 [x86_64-linux-6.1.0-18-amd64] (local build)\nCopyright (C) 2002-23, Bruce Allen, Christian Franke, www.smartmontools.org\n\n=== START OF READ SMART DATA SECTION ===\nSMART Attributes Data Structure revision number: 16\nVendor Specific SMART Attributes with Thresholds:\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\n  1 Raw_Read_Error_Rate     0x000f   082   064   044    Pre-fail  Always       -       164217872\n  3 Spin_Up_Time            0x0003   094   093   000    Pre-fail  Always       -       0\n  4 Start_Stop_Count        0x0032   100   100   020    Old_age   Always       -       59\n  5 Reallocated_Sector_Ct   0x0033   100   100   010    Pre-fail  Always       -       0\n  9 Power_On_Hours          0x0032   091   091   000    Old_age   Always       -       8312\n194 Temperature_Celsius     0x0022   031   046   000    Old_age   Always       -       31 (Min/Max 22/46)\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       0\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       0\n\n"], "expected": {"__tuple__": ["OK", []]}}, {"args": ["smartctl 7.4 2023-08-01 r5530 [x86_64-linux-6.1.0-18-amd64] (local build)\nCopyright (C) 2002-23, Bruce Allen, Christian Franke, www.smartmontools.org\n\n=== START OF READ SMART DATA SECTION ===\nSMART Attributes Data Structure revision number: 16\nVendor Specific SMART Attributes with Thresholds:\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\n  1 Raw_Read_Error_Rate     0x000f   075   060   044    Pre-fail  Always       -       37895528\n  5 Reallocated_Sector_Ct   0x0033   098   098   010    Pre-fail  Always       -       24\n  9 Power_On_Hours          0x0032   071   071   000    Old_age   Always       -       25930\n187 Reported_Uncorrect      0x0032   100   100   000    Old_age   Always       -       0\n194 Temperature_Celsius     0x0022   029   040   000    Old_age   Always       -       29 (0 18 0 0 0)\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       8\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       8\n\n"], "expected": {"__tuple__": ["WARN", [5, 197, 198]]}}, {"args": ["smartctl 7.4 2023-08-01 r5530 [x86_64-linux-6.1.0-18-amd64] (local build)\nCopyright (C) 2002-23, Bruce Allen, Christian Franke, www.smartmontools.org\n\n=== START OF READ SMART DATA SECTION ===\nSMART Attributes Data Structure revision number: 16\nVendor Specific SMART Attributes with Thresholds:\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\n  5 Reallocated_Sector_Ct   0x0033   005   005   010    Pre-fail  Always   FAILING_NOW 2040\n  9 Power_On_Hours          0x0032   060   060   000    Old_age   Always       -       35120\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       0\n198 Offline_Uncorrectable   0x0010   100   100   000    Old_age   Offline      -       0\n\n"], "expected": {"__tuple__": ["FAIL", [5]]}}, {"args": ["smartctl 7.4 2023-08-01 r5530 [x86_64-linux-6.1.0-18-amd64] (local build)\nCopyright (C) 2002-23, Bruce Allen, Christian Franke, www.smartmontools.org\n\n=== START OF READ SMART DATA SECTION ===\nSMART Attributes Data Structure revision number: 16\nVendor Specific SMART Attributes with Thresholds:\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\n  5 Reallocated_Sector_Ct   0x0033   100   100   010    Pre-fail  Always       -       0\n  7 Seek_Error_Rate         0x000f   060   008   030    Pre-fail  Always   In_the_past 72400\n 10 Spin_Retry_Count        0x0013   100   100   097    Pre-fail  Always       -       0\n194 Temperature_Celsius     0x0022   030   038   000    Old_age   Always       -       30 (Min/Max 18/38)\n\n"], "expected": {"__tuple__": ["WARN", [7]]}}, {"args": ["smartctl 7.4 2023-08-01 r5530 [x86_64-linux-6.1.0-18-amd64] (local build)\nCopyright (C) 2002-23, Bruce Allen, Christian Franke, www.smartmontools.org\n\n=== START OF READ SMART DATA SECTION ===\nSMART Attributes Data Structure revision number: 16\nVendor Specific SMART Attributes with Thresholds:\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\n  9 Power_On_Hours          0x0032   099   099   000    Old_age   Always       -       1204\n190 Airflow_Temperature_Cel 0x0022   044   040   045    Old_age   Always       -       56 (Min/Max 30/60)\n194 Temperature_Celsius     0x0022   056   060   000    Old_age   Always       -       56 (Min/Max 30/60)\n199 UDMA_CRC_Error_Count    0x003e   200   200   000    Old_age   Always       -       30\n\n"], "expected": {"__tuple__": ["WARN", [190, 194]]}}, {"args": ["smartctl 7.4 2023-08-01 r5530 [x86_64-linux-6.1.0-18-amd64] (local build)\nCopyright (C) 2002-23, Bruce Allen, Christian Franke, www.smartmontools.org\n\n=== START OF READ SMART DATA SECTION ===\nSMART Attributes Data Structure revision number: 16\nVendor Specific SMART Attributes with Thresholds:\nID# ATTRIBUTE_NAME          FLAG     VALUE WORST THRESH TYPE      UPDATED  WHEN_FAILED RAW_VALUE\n  5 Reallocated_Sector_Ct   0x0033   001   001   010    Pre-fail  Always   FAILING_NOW 65535\n197 Current_Pending_Sector  0x0012   100   100   000    Old_age   Always       -       112\n198 Offline_Uncorrectable   0x0010   003   003   000    Old_age   Offline  FAILING_NOW 112\n"], "expected": {"__tuple__": ["FAIL", [5, 198]]}}, {"args": [""], "expected": {"__tuple__": ["OK", []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-nvme-alerts', 5, 'func', 'Тревоги из NVMe-блока SMART', 'Напишите функцию nvme_alerts(text): text — вывод smartctl -a для NVMe-диска. Интересны строки вида «Поле:   значение»; делите каждую строку по первому двоеточию, а в имени поля сжимайте несколько пробелов в один (в настоящем выводе есть «Warning  Comp. Temperature Time» с двумя пробелами). Числа могут содержать запятые-разделители, знак % и пояснения после числа («12,345 [6.32 TB]»): берите ведущую часть из цифр и запятых. Поле Critical Warning — шестнадцатеричное число вроде 0x04; его биты: 0 — spare, 1 — temperature, 2 — reliability, 3 — read_only, 4 — volatile_backup; за каждый установленный бит добавьте тревогу «critical:<имя>». Дополнительно: «spare_low», если Available Spare строго меньше Available Spare Threshold; «worn», если Percentage Used не меньше 90; «media_errors», если Media and Data Integrity Errors больше нуля; «temp_warning_time», если Warning Comp. Temperature Time больше нуля; «temp_critical_time», если Critical Comp. Temperature Time больше нуля. Остальные поля (в том числе Error Information Log Entries и Unsafe Shutdowns) игнорируйте; отсутствующее поле условия не выполняет. Верните отсортированный список строк.', 'def nvme_alerts(text):
    pass
', 'Соберите словарь «имя поля → строка значения», затем небольшая функция num() берёт ведущие цифры и запятые; биты — (value >> bit) & 1.', '{"func": "nvme_alerts", "tests": [{"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x00\nTemperature:                        38 Celsius\nAvailable Spare:                    100%\nAvailable Spare Threshold:          10%\nPercentage Used:                    3%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    0\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    0\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": []}, {"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x04\nTemperature:                        38 Celsius\nAvailable Spare:                    100%\nAvailable Spare Threshold:          10%\nPercentage Used:                    93%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    1,204\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    0\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": ["critical:reliability", "media_errors", "worn"]}, {"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x01\nTemperature:                        38 Celsius\nAvailable Spare:                    9%\nAvailable Spare Threshold:          10%\nPercentage Used:                    3%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    0\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    0\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": ["critical:spare", "spare_low"]}, {"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x08\nTemperature:                        38 Celsius\nAvailable Spare:                    100%\nAvailable Spare Threshold:          10%\nPercentage Used:                    3%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    0\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    35\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": ["critical:read_only", "temp_warning_time"]}, {"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x1f\nTemperature:                        38 Celsius\nAvailable Spare:                    100%\nAvailable Spare Threshold:          10%\nPercentage Used:                    3%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    0\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    0\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": ["critical:read_only", "critical:reliability", "critical:spare", "critical:temperature", "critical:volatile_backup"]}, {"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x00\nTemperature:                        38 Celsius\nAvailable Spare:                    10%\nAvailable Spare Threshold:          10%\nPercentage Used:                    100%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    0\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    0\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": ["worn"]}, {"args": ["=== START OF SMART DATA SECTION ===\nSMART overall-health self-assessment test result: PASSED\n\nSMART/Health Information (NVMe Log 0x02)\nCritical Warning:                   0x00\nTemperature:                        38 Celsius\nAvailable Spare:                    100%\nAvailable Spare Threshold:          10%\nPercentage Used:                    89%\nData Units Read:                    12,345,678 [6.32 TB]\nData Units Written:                 9,876,543 [5.05 TB]\nHost Read Commands:                 120,334,901\nHost Write Commands:                98,112,004\nController Busy Time:               412\nPower Cycles:                       158\nPower On Hours:                     3,026\nUnsafe Shutdowns:                   12\nMedia and Data Integrity Errors:    0\nError Information Log Entries:      7\nWarning  Comp. Temperature Time:    0\nCritical Comp. Temperature Time:    0\nTemperature Sensor 1:               38 Celsius\nTemperature Sensor 2:               45 Celsius\n"], "expected": []}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-small-write-io', 6, 'func', 'Цена маленькой записи в RAID', 'Напишите функцию small_write_io(level, n, k): сколько обращений к дискам нужно, чтобы записать k кусков (chunk) одной полосы массива из n дисков. Верните кортеж (чтений, записей). raid0: чтений 0, записей k. raid1: чтений 0, записей n×k (каждый кусок на все n зеркал). raid10 с двумя копиями: чтений 0, записей 2×k. raid5 и raid6 (чётностей p = 1 и 2 соответственно; данных d = n − p на полосу, 1 ≤ k ≤ d): драйвер может обновить чётность двумя способами и берёт тот, где меньше чтений. Read-modify-write читает старые данные записываемых кусков и старую чётность (k + p чтений); reconstruct-write читает куски полосы, которые не перезаписываются (d − k чтений). Записей в обоих случаях k + p (новые данные и новая чётность). Верните минимум из двух чтений и k + p записей.', 'def small_write_io(level, n, k):
    pass
', 'Для raid5/6 посчитайте rmw = k + p и rcw = d - k, возьмите min; записей всегда k + p.', '{"func": "small_write_io", "tests": [{"args": ["raid5", 4, 1], "expected": {"__tuple__": [2, 2]}}, {"args": ["raid5", 3, 1], "expected": {"__tuple__": [1, 2]}}, {"args": ["raid5", 8, 1], "expected": {"__tuple__": [2, 2]}}, {"args": ["raid5", 8, 7], "expected": {"__tuple__": [0, 8]}}, {"args": ["raid5", 8, 6], "expected": {"__tuple__": [1, 7]}}, {"args": ["raid6", 6, 1], "expected": {"__tuple__": [3, 3]}}, {"args": ["raid6", 6, 4], "expected": {"__tuple__": [0, 6]}}, {"args": ["raid6", 4, 2], "expected": {"__tuple__": [0, 4]}}, {"args": ["raid1", 2, 1], "expected": {"__tuple__": [0, 2]}}, {"args": ["raid1", 3, 2], "expected": {"__tuple__": [0, 6]}}, {"args": ["raid10", 4, 3], "expected": {"__tuple__": [0, 6]}}, {"args": ["raid0", 4, 2], "expected": {"__tuple__": [0, 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-rebuild-ure', 7, 'func', 'Риск нечитаемого сектора при ребилде', 'Диск выдаёт неисправимую ошибку чтения (URE) с вероятностью 10^(−e) на каждый прочитанный бит; в паспортах пишут «1 на 10^14 бит», то есть e = 14. Напишите функцию rebuild_ure_risk(level, n, size_tb, ure_exp): вероятность хотя бы одной URE, пока массив из n дисков по size_tb терабайт (1 ТБ = 10^12 байт, 1 байт = 8 бит) восстанавливается после отказа одного диска. Модель: ошибки независимы, читаются все данные, нужные для сборки. raid1 и raid10 читают один оставшийся диск-партнёр; raid5 читает все n−1 оставшихся диска; raid6 использует вторую чётность, чтобы исправить первую же ошибку, поэтому для него верните 0.0; raid0 восстановить нельзя — верните None. Вероятность P = 1 − (1 − 10^(−e))^B, где B — число прочитанных бит; верните её, округлив до четырёх знаков после запятой (float). Подсказка: (1 − q)^B лучше считать как exp(B × log1p(−q)).', 'def rebuild_ure_risk(level, n, size_tb, ure_exp):
    pass
', 'Число прочитанных бит B = дисков × size_tb × 8e12; P = -expm1(B × log1p(-10**-e)); raid6 и raid0 разберите заранее.', '{"func": "rebuild_ure_risk", "tests": [{"args": ["raid5", 4, 4, 14], "expected": 0.6171}, {"args": ["raid5", 4, 4, 15], "expected": 0.0915}, {"args": ["raid5", 3, 1, 14], "expected": 0.1479}, {"args": ["raid5", 8, 12, 15], "expected": 0.4893}, {"args": ["raid5", 8, 12, 16], "expected": 0.065}, {"args": ["raid1", 2, 4, 14], "expected": 0.2739}, {"args": ["raid10", 4, 16, 15], "expected": 0.1201}, {"args": ["raid6", 8, 16, 14], "expected": 0.0}, {"args": ["raid0", 2, 1, 14], "expected": null}, {"args": ["raid5", 3, 0.001, 14], "expected": 0.0002}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-mdadm-conf', 8, 'func', 'Сборка mdadm.conf из --detail --scan', 'Напишите функцию make_mdadm_conf(scan, mailaddr): scan — вывод mdadm --detail --scan, mailaddr — адрес для писем (может быть пустой строкой). Из вывода берутся только строки, начинающиеся с «ARRAY » (комментарии, INACTIVE-ARRAY, строки продолжения с отступом пропускаются). У строки ARRAY слова после устройства — признаки; слова, начинающиеся с devices= и spares=, отбрасываются, остальные остаются в прежнем порядке. UUID= обязателен, его значение — четыре группы по восемь строчных шестнадцатеричных цифр через двоеточие; строки без корректного UUID пропускаются. Если UUID уже встречался, повторная строка пропускается. Оставшиеся массивы упорядочите по имени устройства «естественно»: имя режется на куски цифр и не-цифр, цифры сравниваются как числа (/dev/md2 раньше /dev/md10). Результат — текст: первая строка «DEVICE partitions», вторая «MAILADDR <адрес>» (только если адрес не пустой), далее по строке «ARRAY <устройство> <признаки через пробел>». Текст заканчивается переводом строки.', 'def make_mdadm_conf(scan, mailaddr):
    pass
', 'Дедуплицируйте по UUID через set, ключ сортировки — список кусков re.split(r''(\d+)'', dev), где куски-цифры стали int.', '{"func": "make_mdadm_conf", "tests": [{"args": ["ARRAY /dev/md0 metadata=1.2 name=srv1:0 UUID=5b2f1c0e:7d9a4e11:b0c8a3d2:19e4f6a7\nARRAY /dev/md10 metadata=1.2 name=srv1:10 UUID=0a1b2c3d:4e5f6a7b:8c9d0e1f:2a3b4c5d\nARRAY /dev/md2 metadata=1.2 name=srv1:2 UUID=ebe7bfba:a20bf402:f7954545:d920460f\n", "root"], "expected": "DEVICE partitions\nMAILADDR root\nARRAY /dev/md0 metadata=1.2 name=srv1:0 UUID=5b2f1c0e:7d9a4e11:b0c8a3d2:19e4f6a7\nARRAY /dev/md2 metadata=1.2 name=srv1:2 UUID=ebe7bfba:a20bf402:f7954545:d920460f\nARRAY /dev/md10 metadata=1.2 name=srv1:10 UUID=0a1b2c3d:4e5f6a7b:8c9d0e1f:2a3b4c5d\n"}, {"args": ["ARRAY /dev/md0 metadata=1.2 name=srv1:0 UUID=5b2f1c0e:7d9a4e11:b0c8a3d2:19e4f6a7\nARRAY /dev/md10 metadata=1.2 name=srv1:10 UUID=0a1b2c3d:4e5f6a7b:8c9d0e1f:2a3b4c5d\nARRAY /dev/md2 metadata=1.2 name=srv1:2 UUID=ebe7bfba:a20bf402:f7954545:d920460f\n", ""], "expected": "DEVICE partitions\nARRAY /dev/md0 metadata=1.2 name=srv1:0 UUID=5b2f1c0e:7d9a4e11:b0c8a3d2:19e4f6a7\nARRAY /dev/md2 metadata=1.2 name=srv1:2 UUID=ebe7bfba:a20bf402:f7954545:d920460f\nARRAY /dev/md10 metadata=1.2 name=srv1:10 UUID=0a1b2c3d:4e5f6a7b:8c9d0e1f:2a3b4c5d\n"}, {"args": ["# produced on srv1\nINACTIVE-ARRAY /dev/md127 num-devices=2 metadata=1.2 name=srv1:127 UUID=11111111:22222222:33333333:44444444\nARRAY /dev/md/data level=raid5 num-devices=3 metadata=1.2 name=srv1:data UUID=aaaaaaaa:bbbbbbbb:cccccccc:dddddddd\n   devices=/dev/sdb1,/dev/sdc1,/dev/sdd1\nARRAY /dev/md1 level=raid1 num-devices=2 metadata=1.2 name=srv1:1 UUID=ebe7bfba:a20bf402:f7954545:d920460f devices=/dev/sda2,/dev/sdb2\nARRAY /dev/md3 metadata=1.2 name=srv1:3 UUID=ebe7bfba:a20bf402:f7954545:d920460f\n", "admin@example.com"], "expected": "DEVICE partitions\nMAILADDR admin@example.com\nARRAY /dev/md1 level=raid1 num-devices=2 metadata=1.2 name=srv1:1 UUID=ebe7bfba:a20bf402:f7954545:d920460f\nARRAY /dev/md/data level=raid5 num-devices=3 metadata=1.2 name=srv1:data UUID=aaaaaaaa:bbbbbbbb:cccccccc:dddddddd\n"}, {"args": ["ARRAY /dev/md9 metadata=1.2 UUID=not-a-uuid\nARRAY /dev/md8 metadata=0.90 UUID=1a2b3c4d:5e6f7a8b:9c0d1e2f:3a4b5c6d spares=1\n", "ops@example.com"], "expected": "DEVICE partitions\nMAILADDR ops@example.com\nARRAY /dev/md8 metadata=0.90 UUID=1a2b3c4d:5e6f7a8b:9c0d1e2f:3a4b5c6d\n"}, {"args": ["ARRAY /dev/md/boot metadata=1.2 name=h:boot UUID=00000000:00000000:00000000:00000001\nARRAY /dev/md/root metadata=1.2 name=h:root UUID=00000000:00000000:00000000:00000002\nARRAY /dev/md/10 metadata=1.2 name=h:10 UUID=00000000:00000000:00000000:00000003\nARRAY /dev/md/9 metadata=1.2 name=h:9 UUID=00000000:00000000:00000000:00000004\n", ""], "expected": "DEVICE partitions\nARRAY /dev/md/9 metadata=1.2 name=h:9 UUID=00000000:00000000:00000000:00000004\nARRAY /dev/md/10 metadata=1.2 name=h:10 UUID=00000000:00000000:00000000:00000003\nARRAY /dev/md/boot metadata=1.2 name=h:boot UUID=00000000:00000000:00000000:00000001\nARRAY /dev/md/root metadata=1.2 name=h:root UUID=00000000:00000000:00000000:00000002\n"}, {"args": ["", "root"], "expected": "DEVICE partitions\nMAILADDR root\n"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 17, 'la17-smartctl-exit', 9, 'func', 'Код возврата smartctl', 'Код возврата smartctl — битовая маска. Биты (с нуля): 0 — командная строка не разобрана; 1 — устройство не открылось или не отвечает; 2 — команда SMART не выполнилась или контрольная сумма данных неверна; 3 — проверка здоровья вернула «диск отказывает»; 4 — предотказные атрибуты уже на пороге или ниже; 5 — какие-то атрибуты были на пороге или ниже в прошлом; 6 — в журнале ошибок устройства есть записи; 7 — в журнале самотестов есть ошибки. Напишите функцию smartctl_exit(code): сначала возьмите code & 255, затем верните кортеж (серьёзность, список номеров установленных битов по возрастанию). Серьёзность: «critical», если установлен бит 3 или 4; иначе «error», если установлен хотя бы один из битов 0, 1, 2 (smartctl не смог проверить диск); иначе «warning», если установлены какие-то другие биты (5, 6, 7); иначе «ok».', 'def smartctl_exit(code):
    pass
', 'Список битов: [b for b in range(8) if code >> b & 1]; потом проверяйте серьёзность по приоритету critical, error, warning.', '{"func": "smartctl_exit", "tests": [{"args": [0], "expected": {"__tuple__": ["ok", []]}}, {"args": [8], "expected": {"__tuple__": ["critical", [3]]}}, {"args": [16], "expected": {"__tuple__": ["critical", [4]]}}, {"args": [24], "expected": {"__tuple__": ["critical", [3, 4]]}}, {"args": [32], "expected": {"__tuple__": ["warning", [5]]}}, {"args": [64], "expected": {"__tuple__": ["warning", [6]]}}, {"args": [96], "expected": {"__tuple__": ["warning", [5, 6]]}}, {"args": [128], "expected": {"__tuple__": ["warning", [7]]}}, {"args": [4], "expected": {"__tuple__": ["error", [2]]}}, {"args": [3], "expected": {"__tuple__": ["error", [0, 1]]}}, {"args": [40], "expected": {"__tuple__": ["critical", [3, 5]]}}, {"args": [192], "expected": {"__tuple__": ["warning", [6, 7]]}}, {"args": [256], "expected": {"__tuple__": ["ok", []]}}, {"args": [255], "expected": {"__tuple__": ["critical", [0, 1, 2, 3, 4, 5, 6, 7]]}}]}');
